INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64757604', 64757604, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Konsultan Penyusunan Dokumen Analisis Bidang Monitoring dan Evaluasi Pusat Pilar Ekonomi dan Hukum Tata Kelola dan Daerah Regional 2', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Selatan (Kota)', 195000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Pengadaan Jasa Konsultan Penyusun Dokumen Analisis Bidang Monitoring dan Evaluasi yang menangani Pilar Pembangunan Ekonomi dan Hukum Tata Kelola di tingkat Pusat (Tujuan SDGs Nomor 7, 8, 9, 10, 16, dan 17) dan Daerah Regional 2 (Kepulauan Bangka Belitung, Kepulauan Riau, DKI Jakarta, Jawa Tengah, DI Yogyakarta, Jawa Timur, Kalimantan Barat, Kalimantan Tengah, Kalimantan Selatan, Kalimantan Timur, Kalimantan Utara, Bali, Nusa Tenggara Barat, dan Nusa Tenggara Timur) dilakukan dengan tujuan untuk membantu pelaksanaan Koordinasi Strategis Pelaksanaan Tujuan Pembangunan Berkelanjutan/Sustainable Development Goals (TPB/SDGs) Tahun 2026 khususnya bidang monitoring dan evaluasi.', 'a. Membantu mengembangkan format database dan informasi Pilar Pembangunan Ekonomi dan Hukum Tata Kelola di tingkat Pusat dan Daerah Regional 2. b. Melakukan penginputan, menyimpan, dan memutakhirkan data monitoring dan evaluasi dari Kementerian/Lembaga dan nonpemerintah pilar Pilar Pembangunan Ekonomi dan Hukum Tata Kelola di tingkat Pusat dan Daerah Regional 2. c. Menyusun dan menyimpan data monitoring dan evaluasi pelaksanaan TPB/SDGs dari Kementerian/Lembaga dan nonpemerintah Pilar Pembangunan Ekonomi dan Hukum Tata Kelola di tingkat Pusat dan Daerah Regional 2. d. Melakukan komunikasi secara intensif terkait monitoring dan evaluasi baik di tingkat pusat maupun daerah untuk menjamin pemantauan dan pelaporan TPB/SDGs secara regular data dan informasi dari Kementerian/Lembaga dan nonpemerintah Pilar Pembangunan Ekonomi dan Hukum Tata Kelola di tingkat Pusat dan Daerah Regional 2. e. Membantu meningkatkan kapasitas pemantauan dan evaluasi TPB/SDGs pemangku kepentingan Kementerian/Lembaga dan Pilar Pembangunan Ekonomi dan Hukum Tata Kelola di tingkat Pusat dan Daerah Regional 2. f. Memantau pelaksanaan TPB/SDGs semesteran dan tahunan dari Kementerian/Lembaga dan dan Pilar Pembangunan Ekonomi dan Hukum Tata Kelola di tingkat Pusat dan Daerah Regional 2. g. Melakukan fasilitasi dan kunjungan lapangan dalam rangka pelaksanaan monitoring dan evaluasi TPB/SDGs Kementerian/Lembaga dan dan nonpemerintah Pilar Pembangunan Ekonomi dan Hukum Tata Kelola di tingkat Pusat dan Daerah Regional 2. h. Membantu melakukan analisis hasil pemantauan pelaksanaan TPB/SDGs semesteran dan tahunan Kementerian/Lembaga dan dan nonpemerintah Pilar Pembangunan Ekonomi dan Hukum Tata Kelola di tingkat Pusat dan Daerah Regional 2. i. Membantu menyusun laporan pemantauan dan evaluasi capaian pelaksanaan TPB/SDGs Kementerian/Lembaga dan dan nonpemerintah Pilar Pembangunan Ekonomi dan Hukum Tata Kelola di tingkat Pusat dan Daerah Regional 2. j. Membantu mempersiapkan umpan balik laporan pemantauan TPB/SDGs Kementerian/Lembaga dan dan nonpemerintah Pilar Pembangunan Ekonomi dan Hukum Tata Kelola di tingkat Pusat dan Daerah Regional 2. k. Berkoordinasi dengan tim pilar dan bidang lainnya dalam Sekretariat TPB/SDGs dan dengan Manajer Monitoring dan Evaluasi. l. Menyampaikan informasi dan laporan yang baik dan tepat waktu kepada Manajer Monitoring dan Evaluasi serta kepada Kepala Sekretariat koordinasi Nasional SDGs. m. Fasilitasi persiapan dan pelaksanaan SDGs Action Awards 2026, SDGs Annual Conference 2026; n. Membantu tugas-tugas lainnya untuk kepentingan pelaksanaan kegiatan Koordinasi Strategis Pelaksanaan Tujuan Pembangunan Berkelanjutan/Sustainable Development Goals (SDGs).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1751072);
