INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64756344', 64756344, 'analyze_legacy', 'Kab. Banjarnegara', 'kabkota', 'Dinas Kesehatan', 'Pengadaan Belanja Modal Peralatan Studio Video dan Film Puskesmas Rakit 1', 'Barang', 'E-Purchasing', 'Jawa Tengah, Banjarnegara (Kab.)', 14000000, 'January 2026', 'BLUD', 1, 1, '1 tahun', 'Pengadaan Belanja Modal Peralatan Studio Video dan Film Puskesmas Rakit 1 berupa LCD', '1. Ukuran Layar 40–55 inci — ukuran ideal supaya informasi, teks, dan video tampil jelas dari jarak menonton 3–6 meter (ruang tunggu atau area lobi). 2. Resolusi Full HD (1920×1080) atau lebih baik 4K (3840×2160) → Lebih tajam untuk teks medis, presentasi dan video edukasi. 3. Panel & Kontras Panel IPS atau Direct LED LCD→ Sudut pandang lebar dan warna lebih stabil untuk dilihat dari samping. Rasio kontras ≥ 1000:1→ Gambar lebih tajam dengan perbedaan warna terang–gelap yang jelas. 4. Kecerahan (Brightness) ≥ 300–400 nits→ Cukup jelas di ruangan dengan pencahayaan kamar puskesmas. 5. Refresh Rate 60 Hz untuk penggunaan umum sudah memadai→ Tidak perlu tinggi seperti TV gaming kecuali ada konten bergerak cepat. 6. Fitur Konektivitas HDMI (multiple) — menghubungkan PC/laptop untuk tampilan informasi atau presentasi. USB — memutar video/pengumuman dari flash drive. Wi-Fi / Smart TV (opsional) — streaming konten edukasi secara langsung 7. Fitur Tambahan Smart TV OS (Android/Google TV/VidAA/WebOS) → akses aplikasi seperti YouTube untuk edukasi/pengumuman. Anti-glare / Brightness Auto Adjust → nyaman di ruang dengan cahaya variatif. Bezel tipis → tampilan lebih profesional. 8. Ketahanan & Operasional 24/7 Operation (komersial grade bila sering digunakan). Kebijakan garansi & layanan purna jual di Indonesia.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1751675);
