INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64799435', 64799435, 'analyze_legacy', 'Badan Meteorologi, Klimatologi Dan Geofisika', 'central', 'SEKRETARIAT UTAMA BMKG', 'Pemeliharaan Network Operation Center (NOC)', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 200000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 lok', 'Dalam usaha mempertahankan kinerja Network Operation Center (NOC) yang terdiri atas sejumlah perangkat utama dan pendukung, perlu dilaksanakan kegiatan pemeliharaan Network Operation Center (NOC). Tujuan dari Pemeliharaan NOC Secara umum, tujuannya adalah untuk menjamin ketersediaan, keandalan, dan keamanan infrastruktur jaringan yang mendukung seluruh operasional BMKG dalam menyediakan informasi cuaca, iklim, kualitas udara, dan gempa bumi kepada publik dan pihak terkait.', 'Untuk mencapai tujuan yang diharapkan maka ditetapkan ruang lingkup pekerjaan “Pemeliharaan Network Operation Center (NOC)” meliputi Pemeliharaan preventif dan korektif terhadap peralatan di NOC dan Pemeliharaan Peralatan di Ruang Server yang secara rinci terdiri dari: a. Perangkat Display NOC b. Perangkat Visitor Management System c. Perangkat Keras AC Presisi d. Perangkat Keras AC Cassette e. Perangkat DCIM', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1754431);
